#include "engine/scripting/IVisualScriptRuntime.hpp"
#include <algorithm>
#include <map>
#include <optional>
namespace engine::scripting { namespace { class Runtime final:public IVisualScriptRuntime{const IVisualScriptGraph*g_{nullptr};std::vector<std::uint64_t>order_;std::size_t cursor_{0};bool paused_{false};std::map<std::string,PinValue>vars_;std::vector<ScriptBreakpoint>bps_;std::optional<ScriptError>error_;ScriptProfile profile_{};std::string event_;public:bool load(const IVisualScriptGraph&g,std::string&e)override{auto v=g.validate();if(!v.valid()){e=v.errors.front();error_={{"invalid_graph",e,0}};return false;}g_=&g;order_=g.topological_order();cursor_=0;paused_=false;error_.reset();profile_={};return true;}bool set_variable(const std::string&n,const PinValue&v,std::string&e)override{if(n.empty()){e="empty_variable";return false;}vars_[n]=v;return true;}const PinValue*variable(const std::string&n)const override{auto i=vars_.find(n);return i==vars_.end()?nullptr:&i->second;}bool emit_event(const std::string&n,const std::vector<PinValue>&,std::string&e)override{if(!g_){e="runtime_not_loaded";return false;}if(n.empty()){e="empty_event";return false;}event_=n;cursor_=0;paused_=false;return true;}bool step(std::uint32_t count,std::string&e)override{if(!g_){e="runtime_not_loaded";return false;}if(paused_&&cursor_<order_.size()&&at_breakpoint()){return true;}paused_=false;auto amount=std::min<std::size_t>(count,order_.size()-std::min(cursor_,order_.size()));cursor_+=amount;profile_.steps+=amount;profile_.elapsed_ticks+=amount;if(cursor_==order_.size())paused_=true;else if(at_breakpoint())paused_=true;return true;}bool run_until_yield(std::string&e)override{return step(static_cast<std::uint32_t>(order_.size()),e);}bool resume(std::string&e)override{if(!g_){e="runtime_not_loaded";return false;}paused_=false;return step(static_cast<std::uint32_t>(order_.size()),e);}bool add_breakpoint(const ScriptBreakpoint&b,std::string&e)override{if(!g_||!g_->get_node(b.node_id)){e="node_not_found";return false;}auto i=std::find_if(bps_.begin(),bps_.end(),[&](auto&x){return x.node_id==b.node_id;});if(i==bps_.end())bps_.push_back(b);else*i=b;return true;}bool remove_breakpoint(std::uint64_t id)override{auto i=std::remove_if(bps_.begin(),bps_.end(),[&](auto&x){return x.node_id==id;});bool r=i!=bps_.end();bps_.erase(i,bps_.end());return r;}std::vector<ScriptBreakpoint>breakpoints()const override{return bps_;}std::vector<std::string>variables()const override{std::vector<std::string>o;for(const auto&[n,_]:vars_)o.push_back(n);return o;}const ScriptError*last_error()const override{return error_?&*error_:nullptr;}ScriptProfile profile()const override{return profile_;}bool paused()const noexcept override{return paused_;}private:bool at_breakpoint()const{if(cursor_>=order_.size())return false;return std::any_of(bps_.begin(),bps_.end(),[&](const auto&b){return b.enabled&&b.node_id==order_[cursor_];});}};}
std::unique_ptr<IVisualScriptRuntime>create_visual_script_runtime(){return std::make_unique<Runtime>();}
}
